@'
const root=process.cwd(), suffix='?root='+encodeURIComponent(root);
const state=await (await fetch('http://127.0.0.1:4317/api/state'+suffix)).json();
const task=state.tasks.find(t=>t.id==='task_6c49493af99687df92ebdeacfee9581fe83d1373bba187a704dd98495495fbd7');
if (!task?.documents?.length) throw Error('Reference missing from live dashboard');
const {token}=await (await fetch('http://127.0.0.1:4317/api/session')).json();
const response=await fetch('http://127.0.0.1:4317/api/action'+suffix,{method:'POST',headers:{'Content-Type':'application/json','x-dip-token':token},body:JSON.stringify({action:'document-read',args:{id:task.id,path:'docs/plans/markdown-references.md',role:'plan',heading:'Validation'}})});
const read=await response.json();
if(!response.ok || read.sections[0]?.heading!=='Validation') throw Error(JSON.stringify(read));
console.log(JSON.stringify({liveDashboard:true,role:read.role,currentness:read.currentness,heading:read.sections[0].heading,excerptChars:read.sections[0].text.length,proseStoredInTask:task.plan!==null}));
'@ | node --input-type=module
npx.cmd prettier --write QA_REPORT.md
